package tokenbucket

import (
	"errors"
	"sync"
	"time"
)

// Clock is an injectable time source for deterministic testing.
type Clock interface {
	Now() time.Time
}

// TokenBucket is a concurrency-safe token-bucket rate limiter.
type TokenBucket struct {
	mu       sync.Mutex
	capacity float64
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// NewTokenBucket creates a TokenBucket. It returns an error if capacity or
// refill rate are non-positive, or if clock is nil.
func NewTokenBucket(capacity, refillRate float64, clock Clock) (*TokenBucket, error) {
	if capacity <= 0 {
		return nil, errors.New("tokenbucket: capacity must be positive")
	}
	if refillRate <= 0 {
		return nil, errors.New("tokenbucket: refill rate must be positive")
	}
	if clock == nil {
		return nil, errors.New("tokenbucket: clock must not be nil")
	}
	return &TokenBucket{
		capacity: capacity,
		tokens:   capacity,
		rate:     refillRate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// AllowN attempts to consume n tokens. It returns true if enough tokens were
// available after refilling based on elapsed time.
func (tb *TokenBucket) AllowN(n int) bool {
	if n <= 0 {
		return true
	}
	tb.mu.Lock()
	defer tb.mu.Unlock()

	now := tb.clock.Now()
	elapsed := now.Sub(tb.last).Seconds()
	if elapsed > 0 {
		tb.tokens += elapsed * tb.rate
		if tb.tokens > tb.capacity {
			tb.tokens = tb.capacity
		}
		tb.last = now
	}

	if tb.tokens >= float64(n) {
		tb.tokens -= float64(n)
		return true
	}
	return false
}

// Allow is a convenience wrapper for AllowN(1).
func (tb *TokenBucket) Allow() bool {
	return tb.AllowN(1)
}
